-- ---------- change log for later cloud sync ----------
-- The update trigger also bumps version and updated_at. Never set those in the app.
CREATE TRIGGER trg_stock_movements_cl_ins AFTER INSERT ON stock_movements
BEGIN
    INSERT INTO change_log (id, table_name, row_id, operation) VALUES (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6))), 'stock_movements', NEW.id, 'insert');
END;
