-- ---------- views ----------

CREATE VIEW v_batch_stock AS
SELECT b.id AS batch_id, b.product_id, b.batch_no, b.expiry_date,
       COALESCE(SUM(m.qty_delta), 0) AS stock
FROM batches b
LEFT JOIN stock_movements m ON m.batch_id = b.id
WHERE b.deleted_at IS NULL
GROUP BY b.id;

CREATE VIEW v_product_stock AS
SELECT p.id AS product_id, p.name_en, p.name_ur, p.min_stock, p.is_active,
       COALESCE(SUM(s.stock), 0) AS stock_total,
       COALESCE(SUM(CASE WHEN s.expiry_date >= date('now') THEN s.stock ELSE 0 END), 0) AS stock_sellable
FROM products p
LEFT JOIN v_batch_stock s ON s.product_id = p.id
WHERE p.deleted_at IS NULL
GROUP BY p.id;

CREATE VIEW v_low_stock AS
SELECT * FROM v_product_stock WHERE is_active = 1 AND stock_sellable <= min_stock;

CREATE VIEW v_near_expiry AS
SELECT s.batch_id, s.product_id, s.batch_no, s.expiry_date, s.stock,
       CAST(julianday(s.expiry_date) - julianday(date('now')) AS INTEGER) AS days_left
FROM v_batch_stock s
WHERE s.stock > 0
  AND s.expiry_date >= date('now')
  AND s.expiry_date <= date('now', '+' || COALESCE(
        (SELECT CAST(value AS INTEGER) FROM settings WHERE "key" = 'near_expiry_days' AND deleted_at IS NULL), 30) || ' days');

CREATE VIEW v_expired_stock AS
SELECT * FROM v_batch_stock WHERE stock > 0 AND expiry_date < date('now');

CREATE VIEW v_customer_balance AS
SELECT c.id AS customer_id, c.name_en, c.name_ur, c.phone, c.credit_limit,
       COALESCE(SUM(l.amount_delta), 0) AS balance
FROM customers c
LEFT JOIN ledger_entries l ON l.party_type = 'customer' AND l.party_id = c.id
WHERE c.deleted_at IS NULL
GROUP BY c.id;

CREATE VIEW v_supplier_balance AS
SELECT s.id AS supplier_id, s.name_en, s.name_ur, s.phone,
       COALESCE(SUM(l.amount_delta), 0) AS balance
FROM suppliers s
LEFT JOIN ledger_entries l ON l.party_type = 'supplier' AND l.party_id = s.id
WHERE s.deleted_at IS NULL
GROUP BY s.id;

CREATE VIEW v_invoice_item_returnable AS
SELECT ii.id AS invoice_item_id, ii.invoice_id, ii.qty AS qty_sold,
       COALESCE((SELECT SUM(qty) FROM sales_return_items WHERE invoice_item_id = ii.id), 0) AS qty_returned,
       ii.qty - COALESCE((SELECT SUM(qty) FROM sales_return_items WHERE invoice_item_id = ii.id), 0) AS qty_returnable
FROM invoice_items ii;

CREATE VIEW v_invoice_mismatch AS
SELECT i.id AS invoice_id, i.invoice_no, i.total, COALESCE(SUM(ii.line_total), 0) AS lines_total
FROM invoices i
LEFT JOIN invoice_items ii ON ii.invoice_id = i.id
GROUP BY i.id
HAVING i.total <> COALESCE(SUM(ii.line_total), 0);

CREATE VIEW v_profit_by_day AS
SELECT day,
       CAST(SUM(revenue) AS INTEGER) AS revenue,
       CAST(SUM(cost) AS INTEGER) AS cost,
       CAST(SUM(revenue) - SUM(cost) AS INTEGER) AS profit
FROM (
    SELECT date(i.invoice_date) AS day,
           ii.line_total - ii.tax_amount AS revenue,
           CAST(ROUND(ii.cost_price * ii.qty * 1.0 / p.pack_size) AS INTEGER) AS cost
    FROM invoice_items ii
    JOIN invoices i ON i.id = ii.invoice_id
    JOIN products p ON p.id = ii.product_id
    WHERE i.status = 'active'
    UNION ALL
    SELECT date(r.return_date),
           -CAST(ROUND(sri.refund_amount * 1.0 * (ii.line_total - ii.tax_amount) / NULLIF(ii.line_total, 0)) AS INTEGER),
           -CASE WHEN sri.condition = 'resellable'
                 THEN CAST(ROUND(ii.cost_price * sri.qty * 1.0 / p.pack_size) AS INTEGER) ELSE 0 END
    FROM sales_return_items sri
    JOIN sales_returns r ON r.id = sri.sales_return_id
    JOIN invoice_items ii ON ii.id = sri.invoice_item_id
    JOIN invoices i ON i.id = r.invoice_id
    JOIN products p ON p.id = ii.product_id
    WHERE i.status = 'active'
)
GROUP BY day;

